use crate::{config,icon,popup,probes::proxy,state::Snapshot,AppState};use tauri::menu::{CheckMenuItem,Menu,MenuItem,PredefinedMenuItem};use tauri::tray::{MouseButton,MouseButtonState,TrayIconBuilder,TrayIconEvent};use tauri::{AppHandle,Manager};
pub const TRAY_ID:&str="main-tray";
pub fn build(app:&AppHandle)->tauri::Result<()>{let open=MenuItem::with_id(app,"open","داشبورد و آمار",true,None::<&str>)?;let check=MenuItem::with_id(app,"check","بررسی مجدد",true,None::<&str>)?;let prx=MenuItem::with_id(app,"proxy","خاموش‌کردن پروکسی سیستم",true,None::<&str>)?;let quiet=CheckMenuItem::with_id(app,"quiet","حالت سکوت",true,false,None::<&str>)?;let quit=MenuItem::with_id(app,"quit","خروج",true,None::<&str>)?;let sep=PredefinedMenuItem::separator(app)?;let menu=Menu::with_items(app,&[&open,&check,&prx,&quiet,&sep,&quit])?;TrayIconBuilder::with_id(TRAY_ID).icon(icon::make([120,120,120,255],None)).tooltip("NetWatch").menu(&menu).show_menu_on_left_click(false).on_menu_event(|app,e|match e.id().as_ref(){"open"=>popup::open_dashboard(app),"check"=>app.state::<AppState>().kick.notify_one(),"proxy"=>{let _=proxy::disable();app.state::<AppState>().kick.notify_one()},"quiet"=>{let st=app.state::<AppState>();let mut settings=st.settings.write();settings.quiet=!settings.quiet;let _=config::save(&st.settings_path.lock(),&settings);},"quit"=>app.exit(0),_=>{}}).on_tray_icon_event(|tray,e|{let app=tray.app_handle();let rect=match &e{TrayIconEvent::Click{rect,..}|TrayIconEvent::DoubleClick{rect,..}|TrayIconEvent::Enter{rect,..}|TrayIconEvent::Move{rect,..}|TrayIconEvent::Leave{rect,..}=>Some(rect),_=>None};if let Some(rect)=rect{let scale=app.primary_monitor().ok().flatten().map(|m|m.scale_factor()).unwrap_or(1.0);let p=rect.position.to_logical::<f64>(scale);let size=rect.size.to_logical::<f64>(scale);if size.width>0.0{*app.state::<AppState>().tray_rect.lock()=Some((p.x,p.y,size.width,size.height));}}if let TrayIconEvent::Click{button:MouseButton::Left,button_state:MouseButtonState::Up,..}=e{popup::open_dashboard(&app)}}).build(app)?;Ok(())}
pub fn update(app:&AppHandle,s:&Snapshot){if let Some(t)=app.tray_by_id(TRAY_ID){let _=t.set_icon(Some(icon::make(s.state.color(),None)));let mut tip=format!("{} {}",s.state.emoji(),s.state.title());if s.via_vpn{tip.push_str(&format!("\n🛡️ VPN فعال — خروجی: {} {}",s.exit.country.clone().unwrap_or_default(),s.exit.ip.clone().unwrap_or_default()));}else if let Some(tun)=&s.tun{tip.push_str(&format!("\nTUN بالا ولی خروجی ایران است: {tun}"));}else if s.proxy.configured{tip.push_str(&format!("\nپروکسی {}:{} {}",s.proxy.host,s.proxy.port,if s.proxy.listening{"روشن ولی کار نمی‌کند ✗"}else{"بسته ✗"}));}if let Some(ms)=s.vpn_ping{tip.push_str(&format!(" | تونل: {ms}ms"));}if let Some(note)=&s.note{tip.push_str(&format!("\n{note}"));}let _=t.set_tooltip(Some(tip));}}
pub fn spin(app:&AppHandle){if let Some(t)=app.tray_by_id(TRAY_ID){let _=t.set_icon(Some(icon::make([120,120,120,255],None)));}}
